		const DEFAULT_PRESENTATION = {
			mode: "standard",
			reduceMotion: false
		};
		const PRESENTATION_STORAGE_KEY = "dsh-whale-companion:presentation:v1";
		function parsePresentation(raw) {
			if (raw === null) return DEFAULT_PRESENTATION;
			try {
				const value = JSON.parse(raw);
				if (value.mode !== "quiet" && value.mode !== "standard" && value.mode !== "lively" || typeof value.reduceMotion !== "boolean") return DEFAULT_PRESENTATION;
				return {
					mode: value.mode,
					reduceMotion: value.reduceMotion
				};
			} catch {
				return DEFAULT_PRESENTATION;
			}
		}
		function readPresentation(storage) {
			if (storage === void 0) return {
				value: DEFAULT_PRESENTATION,
				available: false
			};
			try {
				return {
					value: parsePresentation(storage.getItem(PRESENTATION_STORAGE_KEY)),
					available: true
				};
			} catch {
				return {
					value: DEFAULT_PRESENTATION,
					available: false
				};
			}
		}
		function writePresentation(storage, value) {
			if (storage === void 0) return false;
			try {
				storage.setItem(PRESENTATION_STORAGE_KEY, JSON.stringify(value));
				return true;
			} catch {
				return false;
			}
		}
		function browserStorage() {
			try {
				return window.localStorage;
			} catch {
				return;
			}
		}
